SELECT , u.nick_name AS user_nick_name, u.avatar AS user_avatar FROM feed f LEFT JOIN sys_user u ON f.user_id = u.user_id
f.status = 'normal' AND f.audit_status = 'approved' AND f.tenant_id = #{tenantId}
AND ( f.visibility = 'public' OR f.user_id = #{userId} OR EXISTS ( SELECT 1 FROM user_relation ur WHERE ur.user_id = #{userId} AND ur.target_user_id = f.user_id ) )
AND f.hot_score >= #{maxHotScore}
ORDER BY f.hot_score DESC, f.publish_time DESC
ORDER BY f.publish_time DESC

SELECT ,
       u.nick_name AS user_nick_name,
       u.avatar AS user_avatar
FROM feed f
LEFT JOIN sys_user u ON f.user_id = u.user_id
WHERE f.user_id = #{userId}
AND f.tenant_id = #{tenantId}

    AND f.visibility = #{visibility}

ORDER BY f.publish_time DESC

mapper.update:
UPDATE feed
content = #{content}, images = #{images}, related_product_id = #{relatedProductId}, visibility = #{visibility}, audit_status = 'pending', update_time = NOW()
WHERE feed_id = #{feedId} AND tenant_id = #{tenantId}

UPDATE feed SET
    status = #{status},
    audit_status = #{auditStatus},
    update_time = NOW()
WHERE feed_id = #{feedId}
AND tenant_id = #{tenantId}

UPDATE feed SET
    status = #{status},
    audit_status = #{auditStatus},
    update_time = NOW()
WHERE feed_id = #{feedId}
  AND status <> #{excludeStatus}
AND tenant_id = #{tenantId}

